#pragma once
// Reflection: type tables generated by tools/reflect (lsd_reflect_gen) from annotated headers.
// The tables drive the Details panel, save/load, undo and (later) visual-script nodes and Lua.
//
//   LSD_STRUCT(Component, Category = "Lights")
//   struct PointLight {
//       LSD_GENERATED()
//       LSD_PROPERTY(Edit, Category = "Light", Units = "lumens", Min = 0)
//       f32 intensity = 800.0f;
//   };
//
// Struct flags:   Component, Color, Vector
// Property flags: Edit (editable in Details), Visible (read-only in Details), Save (saved, hidden),
//                 EditorOnly (stripped at packaging). Edit and Visible imply Save.
// Property keys:  Category, Tooltip, Units (strings); Min, Max (numbers); Widget (editor hint):
//                 "Choice:A,B,C" (u32 / i32 shown as a dropdown, like an enum), "Asset:<Type>" (a char[33]
//                 asset GUID picked from the Content Browser), "Key" (an input key name).
// Lists:          List<T, N> fields (fixed capacity, count + items, still plain data) save as JSON arrays.
// Function flags: Callable.
#include "lsd/foundation/hash_id.h"
#include "lsd/foundation/reflect_macros.h"
#include "lsd/foundation/types.h"

namespace lsd::reflect {

// String = fixed-size `char name[N]` (always NUL-terminated, truncated to fit). Array = a List<T, N>.
enum class FieldType : u8 { Bool, I32, U32, I64, U64, F32, F64, String, Struct, Array };

// Fixed-capacity list for reflected structs: no allocation, so the owner stays plain data
// (copyable with memcpy, savable, undoable). Like TArray with a hard limit.
template <typename T, u32 N>
struct List {
    u32 count = 0;
    T items[N];

    static constexpr u32 capacity() { return N; }
    T* begin() { return items; }
    T* end() { return items + count; }
    const T* begin() const { return items; }
    const T* end() const { return items + count; }
    T& operator[](u32 i) { return items[i]; }
    const T& operator[](u32 i) const { return items[i]; }
    // False when full.
    bool push_back(const T& value) {
        if (count == N) return false;
        items[count++] = value;
        return true;
    }
    void remove(u32 i) {  // keeps order
        if (i >= count) return;
        for (u32 k = i; k + 1 < count; ++k) items[k] = items[k + 1];
        --count;
    }
};

// Where a List's items start (generated code uses it; offsetof does not accept these types).
template <typename L> struct ListTraits;
template <typename T, u32 N>
struct ListTraits<List<T, N>> {
    static constexpr u32 items_offset = static_cast<u32>((sizeof(u32) + alignof(T) - 1) / alignof(T) * alignof(T));
};

enum PropertyFlags : u32 {
    kEdit       = 1u << 0,
    kVisible    = 1u << 1,
    kSave       = 1u << 2,
    kEditorOnly = 1u << 3,
};

enum TypeFlags : u32 {
    kComponent = 1u << 0,
    kColor     = 1u << 1,  // r, g, b[, a] f32 fields in that order: edited with a colour picker
    kVector    = 1u << 2,  // x, y, z f32 fields: edited on one row, like Unreal's X / Y / Z boxes
};

struct TypeInfo;

struct Property {
    const char* name;
    FieldType type;
    u32 offset;
    u32 size;  // bytes; for String the capacity including the NUL
    u32 flags;
    const char* category;  // "" when not set
    const char* tooltip;
    const char* units;
    f64 min;
    f64 max;
    bool has_min;
    bool has_max;
    const TypeInfo* struct_type;  // set when type == Struct, or Array of structs
    const char* widget = "";      // editor hint (see Widget above)
    // Array only: the count is a u32 at `offset`; the items start at offset + items_offset.
    FieldType element_type = FieldType::Bool;
    u32 element_size = 0;
    u32 capacity = 0;
    u32 items_offset = 0;
};

// The element of an Array property described as a Property of its own (for per-element code).
Property element_property(const Property& array);

struct TypeInfo {
    const char* name;
    HashId id;
    u32 size;
    u32 alignment;
    u32 flags;
    const char* category;
    const Property* properties;
    u32 property_count;
    const void* defaults;  // a default-constructed instance: new components start as a copy of it
    const char* tooltip = "";  // what it is for (LSD_STRUCT Tooltip): + Add Component shows it
};

template <typename T>
const TypeInfo& type_of() { return T::static_type(); }

} // namespace lsd::reflect

namespace lsd {
using reflect::List;  // reflected structs in any lsd namespace can write List<T, N>
} // namespace lsd

namespace lsd::reflect {

const Property* find_property(const TypeInfo& type, const char* name);

// Text save format: JSON objects of the saved properties, nested structs as nested objects.
// Writes at most capacity-1 chars plus a NUL; returns the full length so callers can grow and retry.
// depth > 0 indents the object for embedding in a bigger document (no trailing newline then).
usize save_text(const TypeInfo& type, const void* object, char* out, usize capacity, u32 depth = 0);

// Reads text produced by save_text. Missing keys keep their current values and unknown keys are
// skipped, so old files load after properties are added or removed. Returns false on bad syntax
// or out-of-range values; the object may then be partly loaded, so load into a copy if that matters.
bool load_text(const TypeInfo& type, void* object, const char* text, usize length);

// File helpers. load_file reads into a copy first, so a bad or missing file leaves the object unchanged.
// Reflected structs are plain data (no inheritance, no pointers), so a byte copy is a valid copy.
bool save_file(const TypeInfo& type, const void* object, const char* path);
bool load_file(const TypeInfo& type, void* object, const char* path);

template <typename T>
bool save_file(const T& object, const char* path) { return save_file(type_of<T>(), &object, path); }

template <typename T>
bool load_file(T& object, const char* path) { return load_file(type_of<T>(), &object, path); }

// Binary format for compiled data: per property its name hash, byte size and bytes, so files
// still load after properties are added, removed or reordered (unknown or resized ones are skipped).
// Same capacity contract as save_text.
usize save_binary(const TypeInfo& type, const void* object, u8* out, usize capacity);
bool load_binary(const TypeInfo& type, void* object, const u8* data, usize size);

template <typename T>
usize save_binary(const T& object, u8* out, usize capacity) { return save_binary(type_of<T>(), &object, out, capacity); }

template <typename T>
usize save_text(const T& object, char* out, usize capacity) { return save_text(type_of<T>(), &object, out, capacity); }

template <typename T>
bool load_text(T& object, const char* text, usize length) { return load_text(type_of<T>(), &object, text, length); }

} // namespace lsd::reflect
